dtsPropsFor.Headword:
/** The word as written in the source. */
  form: string;
  /** Character range of the stressed syllable, as underlined in the source. Omit when the source marks nothing. */
  stress?: { start: number; end: number };
  /** BCP 47 tag of the language, e.g. "mcm" for Kristang. */
  lang: string;

dtsPropsFor.HegelCompanion:
/** The heading and supporting sentence Hegel sits beside. */
  children: React.ReactNode;
  /** Smaller portrait for completion screens. */
  compact?: boolean;
  /** Image for the portrait. In a design, pass `window.Kambradu.hegelPortrait`; the app's default path does not resolve outside the app. */
  portraitSrc?: string;

dtsPropsFor.VariantNote:
/** Other attested forms of the word. "spelling" is the same sound written differently; "form" sounds different. None is ranked. */
  variants: Array<{ form: string; orthography: string; kind: "spelling" | "form"; note?: string }>;
  /** BCP 47 tag of the language, e.g. "mcm" for Kristang. */
  lang: string;

dtsPropsFor.AppShell:
/** The screen's content. */
  children: React.ReactNode;
  /** Path of the current screen, used to mark the active tab: "/", "/learn" or "/memories". */
  activePath?: string;
  /** Practice mode: hides navigation and shows a quiet "Leave practice" link. */
  immersive?: boolean;
